  function settingsPage(){const job=data.syncJob,timer=data.setup.syncTimer||{},timerLabel=timer.state!=='available'?'Status unavailable':(timer.enabled?'Enabled':'Disabled')+' · '+(timer.active?'active':'inactive'),backup=data.setup.backup||{},backupTimer=backup.timer||{},backupTimerLabel=backupTimer.state!=='available'?'Status unavailable':(backupTimer.enabled?'Enabled':'Disabled')+' · '+(backupTimer.active?'active':'inactive'),backupState={success:'Verified backup available',failed:'Latest backup attempt failed',not_configured:'Not configured for SQLite',not_run:'No backup has run yet',unavailable:'Status unavailable'}[backup.state]||'Status unavailable',jobFailures=(job?.failures||[]).map(f=>'<li>'+esc(f.bank)+': '+esc(f.message)+'</li>').join('');return '<section class="card setup-panel"><h2>Sync timer</h2><p>'+(timerLabel)+'. '+(timer.nextRun?'Next run: '+esc(timer.nextRun):'No next run is scheduled.')+'</p><p class="card-sub">The daily local timer is an optional owner managed service. Ledger reports its systemd state but does not enable or activate it.</p></section><section class="card setup-panel"><h2>Latest sync job</h2>'+(job?'<div class="budget-label"><span>Status</span><b>'+esc(job.status)+'</b></div><div class="budget-label"><span>Started</span><b>'+esc(job.startedAt||'—')+'</b></div><div class="budget-label"><span>Connections checked</span><b>'+esc(String(job.completed||0))+' / '+esc(String(job.total||0))+'</b></div>'+(jobFailures?'<ul class="setup-warning">'+jobFailures+'</ul>':'<p class="card-sub">No connection errors were recorded for this job.</p>'):'<p class="card-sub">No sync job has run yet.</p>')+'</section><section class="card setup-panel"><h2>Local recovery backups</h2><div class="budget-label"><span>Status</span><b>'+esc(backupState)+'</b></div><div class="budget-label"><span>Last attempt</span><b>'+esc(backup.lastAttempt||'—')+'</b></div><div class="budget-label"><span>Last verified success</span><b>'+esc(backup.lastSuccess||'—')+'</b></div>'+(backup.failureCategory?'<p class="setup-warning">Failure category: '+esc(backup.failureCategory)+'</p>':'')+'<p class="card-sub">Daily SQLite backups are verified before publication. Retention keeps seven recent daily and four weekly restore points, plus protected migration backups. Timer: '+esc(backupTimerLabel)+'. '+(backupTimer.nextRun?'Next run: '+esc(backupTimer.nextRun):'No next run is scheduled.')+'</p></section><section class="card setup-panel"><h2>Local recovery</h2><p>Your records and backups stay on this device. Keep the private configuration and encryption key with recovery instructions; Ledger does not upload backup data.</p></section>';}
